import { NextResponse, type NextRequest } from 'next/server'
import { z } from 'zod'
import { logger } from '@/lib/logger'
import { logAuditAction } from '@/lib/audit'
import { createServiceRoleClient } from '@/lib/supabase/server'
import { RPC, type Nec1099AggregateResult, type Nec1099ExportRecordArgs } from '@/lib/payments/contracts'
import { adminExportRatelimit } from '@/lib/rate-limit'
import { requirePlatformAdmin } from '@/lib/admin/require-platform-admin'
import { getClientIp } from '@/lib/rate-limit/get-client-ip'

const BodySchema = z.object({
  studioId: z.string().uuid(),
  year: z.number().int().min(2024).max(2099),
})

export async function POST(req: NextRequest): Promise<Response> {
  const auth = await requirePlatformAdmin(req)
  if (auth instanceof NextResponse) return auth

  const ip = getClientIp(req)
  const rl = await adminExportRatelimit.limit(ip)
  if (!rl.success) {
    return NextResponse.json({ error: 'rate_limited' }, { status: 429 })
  }

  let body: unknown
  try {
    body = await req.json()
  } catch {
    return NextResponse.json({ error: 'invalid_json' }, { status: 400 })
  }

  const parsed = BodySchema.safeParse(body)
  if (!parsed.success) {
    return NextResponse.json({ error: 'validation', issues: parsed.error.issues }, { status: 400 })
  }

  const supabase = createServiceRoleClient()

  // §S13.3 — nec_1099_aggregate not yet in generated types.ts; cast to untyped rpc.
  const rpc = supabase.rpc.bind(supabase) as unknown as (
    fn: string,
    args: Record<string, unknown>,
  ) => Promise<{ data: unknown; error: { message: string } | null }>

  const { data, error } = await rpc(RPC.NEC_1099_AGGREGATE, {
    p_studio_id: parsed.data.studioId,
    p_year: parsed.data.year,
  })

  if (error) {
    logger.error(
      { studio_id: parsed.data.studioId, year: parsed.data.year, err: error },
      'nec_1099_aggregate RPC failed',
    )
    return NextResponse.json({ error: 'export_failed' }, { status: 500 })
  }

  const result = data as Nec1099AggregateResult

  // §S13.3 — nec_1099_exports not yet in generated types.ts; cast to untyped rpc.
  const rpcUpsert = supabase.rpc.bind(supabase) as unknown as (
    fn: string,
    args: Record<string, unknown>,
  ) => Promise<{ data: unknown; error: { message: string } | null }>

  const thresholdMet = result.artists.filter((a) => a.nec_threshold_met)

  for (const artist of thresholdMet) {
    const exportArgs: Nec1099ExportRecordArgs = {
      studioId: parsed.data.studioId,
      year: result.year,
      artistId: artist.artist_id,
      totalPaidCents: artist.total_paid_cents,
      federalIdLast4: null,
      stateIdLast4: null,
      csvUrl: null,
      pdfUrl: null,
      source: 'stripe',
    }

    const { error: upsertError } = await rpcUpsert(RPC.NEC_1099_EXPORT_RECORD, {
      p_studio_id: exportArgs.studioId,
      p_year: exportArgs.year,
      p_artist_id: exportArgs.artistId,
      p_total_paid_cents: exportArgs.totalPaidCents,
      p_federal_id_last4: exportArgs.federalIdLast4,
      p_state_id_last4: exportArgs.stateIdLast4,
      p_csv_url: exportArgs.csvUrl,
      p_pdf_url: exportArgs.pdfUrl,
      p_source: exportArgs.source,
    })

    if (upsertError) {
      logger.error(
        { artist_id: artist.artist_id, studio_id: parsed.data.studioId, err: upsertError },
        'nec_1099_export_record upsert failed',
      )
    }
  }

  // Build CSV — all artists (not just threshold met) for full picture
  const lines: string[] = []
  lines.push('artist_id,artist_name,total_paid_cents,nec_threshold_met,stripe_1099_capable')
  for (const artist of result.artists) {
    lines.push(
      [
        artist.artist_id,
        `"${artist.artist_name.replace(/"/g, '""')}"`,
        artist.total_paid_cents,
        artist.nec_threshold_met ? 'true' : 'false',
        artist.stripe_1099_capable ? 'true' : 'false',
      ].join(','),
    )
  }
  lines.push(`IRS_THRESHOLD_CENTS,60000,,,`)
  lines.push(`TOTAL_THRESHOLD_MET,${result.threshold_met_count},,,`)
  const csv = lines.join('\n') + '\n'

  await logAuditAction(
    auth.userId,
    'admin_nec_1099_export',
    { type: 'studio', id: parsed.data.studioId },
    {
      year: parsed.data.year,
      studio_id: parsed.data.studioId,
      total_artists: result.total_artists,
      threshold_met_count: result.threshold_met_count,
    },
    parsed.data.studioId,
  )

  return new Response(csv, {
    status: 200,
    headers: {
      'Content-Type': 'text/csv; charset=utf-8',
      'Content-Disposition': `attachment; filename="nec1099-${parsed.data.studioId}-${parsed.data.year}.csv"`,
    },
  })
}

/**
 * GET  /api/settings/payments/tax-documents  — list studio's 1099-NEC exports
 * POST /api/settings/payments/tax-documents  — trigger generation for a year
 *
 * §S13.3 — nec_1099_exports not yet in generated types.ts (Dato migration pending).
 * Queries use untyped cast with `data as unknown as T`.
 */
import { NextRequest, NextResponse } from 'next/server'
import { z } from 'zod'
import { getAuthenticatedUser, createServiceRoleClient } from '@/lib/supabase/server'
import { authedRatelimit, expensiveRatelimit } from '@/lib/rate-limit'
import { RPC, type Nec1099AggregateResult, type Nec1099ExportRecordArgs } from '@/lib/payments/contracts'
import { logAuditAction } from '@/lib/audit'
import { logger } from '@/lib/logger'

const PostBodySchema = z.object({
  year: z.number().int().min(2024).max(2099),
})

// ---------------------------------------------------------------------------
// GET — list exports for the studio
// ---------------------------------------------------------------------------

export async function GET(req: NextRequest) {
  const ip = req.headers.get('x-forwarded-for') ?? 'unknown'
  const rl = await authedRatelimit.limit(ip)
  if (!rl.success) {
    return NextResponse.json({ error: 'Too many requests.' }, { status: 429 })
  }

  const auth = await getAuthenticatedUser()
  if (!auth) {
    return NextResponse.json({ error: 'Unauthorized.' }, { status: 401 })
  }

  if (auth.role !== 'owner' && auth.role !== 'admin') {
    return NextResponse.json({ error: 'Owner or admin role required.' }, { status: 403 })
  }

  const supabase = createServiceRoleClient()

  try {
    // §S13.3 — nec_1099_exports not yet in generated types; untyped cast.
    const fromUntyped = supabase.from.bind(supabase) as unknown as (
      table: string,
    ) => ReturnType<typeof supabase.from>

    const { data, error } = await fromUntyped('nec_1099_exports')
      .select('id, year, artist_id, total_paid_cents, nec_threshold_met, source, generated_at, csv_url')
      .eq('studio_id', auth.studioId)
      .order('year', { ascending: false })
      .order('total_paid_cents', { ascending: false })

    if (error) {
      logger.error({ err: error, studioId: auth.studioId }, 'tax-documents GET: query failed')
      return NextResponse.json({ error: 'Could not load tax documents.' }, { status: 500 })
    }

    return NextResponse.json({ exports: data ?? [] })
  } catch (err) {
    logger.error({ err, studioId: auth.studioId }, 'tax-documents GET: unexpected error')
    return NextResponse.json({ error: 'Could not load tax documents.' }, { status: 500 })
  }
}

// ---------------------------------------------------------------------------
// POST — generate for a year (owner only)
// ---------------------------------------------------------------------------

export async function POST(req: NextRequest) {
  const ip = req.headers.get('x-forwarded-for') ?? 'unknown'

  const auth = await getAuthenticatedUser()
  if (!auth) {
    return NextResponse.json({ error: 'Unauthorized.' }, { status: 401 })
  }

  if (auth.role !== 'owner') {
    return NextResponse.json({ error: 'Owner role required to generate tax documents.' }, { status: 403 })
  }

  // Generation is heavier — use expensiveRatelimit
  const rl = await expensiveRatelimit.limit(ip)
  if (!rl.success) {
    return NextResponse.json({ error: 'Too many requests.' }, { status: 429 })
  }

  let body: unknown
  try {
    body = await req.json()
  } catch {
    return NextResponse.json({ error: 'invalid_json' }, { status: 400 })
  }

  const parsed = PostBodySchema.safeParse(body)
  if (!parsed.success) {
    return NextResponse.json({ error: 'validation', issues: parsed.error.issues }, { status: 400 })
  }

  const supabase = createServiceRoleClient()

  // §S13.3 — nec_1099_aggregate not yet in generated types.ts; cast to untyped rpc.
  const rpc = supabase.rpc.bind(supabase) as unknown as (
    fn: string,
    args: Record<string, unknown>,
  ) => Promise<{ data: unknown; error: { message: string } | null }>

  const { data, error } = await rpc(RPC.NEC_1099_AGGREGATE, {
    p_studio_id: auth.studioId,
    p_year: parsed.data.year,
  })

  if (error) {
    logger.error(
      { studioId: auth.studioId, year: parsed.data.year, err: error },
      'nec_1099_aggregate RPC failed (owner trigger)',
    )
    return NextResponse.json({ error: 'Generation failed. Please try again.' }, { status: 500 })
  }

  const result = data as Nec1099AggregateResult
  const thresholdMet = result.artists.filter((a) => a.nec_threshold_met)

  for (const artist of thresholdMet) {
    const exportArgs: Nec1099ExportRecordArgs = {
      studioId: auth.studioId,
      year: result.year,
      artistId: artist.artist_id,
      totalPaidCents: artist.total_paid_cents,
      federalIdLast4: null,
      stateIdLast4: null,
      csvUrl: null,
      pdfUrl: null,
      source: 'stripe',
    }

    const { error: upsertError } = await rpc(RPC.NEC_1099_EXPORT_RECORD, {
      p_studio_id: exportArgs.studioId,
      p_year: exportArgs.year,
      p_artist_id: exportArgs.artistId,
      p_total_paid_cents: exportArgs.totalPaidCents,
      p_federal_id_last4: exportArgs.federalIdLast4,
      p_state_id_last4: exportArgs.stateIdLast4,
      p_csv_url: exportArgs.csvUrl,
      p_pdf_url: exportArgs.pdfUrl,
      p_source: exportArgs.source,
    })

    if (upsertError) {
      logger.error(
        { artistId: artist.artist_id, studioId: auth.studioId, err: upsertError },
        'nec_1099_export_record upsert failed (owner trigger)',
      )
    }
  }

  await logAuditAction(
    auth.user.id,
    'nec_1099_export_generated',
    { type: 'studio', id: auth.studioId },
    {
      year: parsed.data.year,
      threshold_met_count: thresholdMet.length,
      total_artists: result.total_artists,
    },
    auth.studioId,
  )

  return NextResponse.json(
    { year: parsed.data.year, generated_count: thresholdMet.length },
    { status: 201 },
  )
}

