'use client'

import { useState } from 'react'
import { toast } from 'sonner'
import { Card, CardContent, CardHeader } from '@/components/ui/card'
import { Button } from '@/components/ui/button'
import {
  Table,
  TableBody,
  TableCell,
  TableHead,
  TableHeader,
  TableRow,
} from '@/components/ui/table'

export interface Nec1099ExportRow {
  id: string
  year: number
  artist_id: string
  total_paid_cents: number
  nec_threshold_met: boolean | null
  source: string
  generated_at: string
  csv_url: string | null
}

interface TaxDocumentsClientProps {
  initialExports: Nec1099ExportRow[]
}

function formatDollars(cents: number): string {
  return new Intl.NumberFormat('en-US', {
    style: 'currency',
    currency: 'USD',
    minimumFractionDigits: 2,
  }).format(cents / 100)
}

function formatDate(iso: string): string {
  return new Date(iso).toLocaleDateString('en-US', {
    year: 'numeric',
    month: 'short',
    day: 'numeric',
  })
}

export default function TaxDocumentsClient({ initialExports }: TaxDocumentsClientProps) {
  const [exports, setExports] = useState<Nec1099ExportRow[]>(initialExports)
  const [generating, setGenerating] = useState(false)

  const currentYear = new Date().getFullYear()

  async function handleGenerate() {
    setGenerating(true)
    try {
      const res = await fetch('/api/settings/payments/tax-documents', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ year: currentYear }),
      })

      if (!res.ok) {
        const body = (await res.json().catch(() => ({}))) as { error?: string }
        toast.error(body.error ?? 'Generation failed. Please try again.')
        return
      }

      const generated = (await res.json()) as { year: number; generated_count: number }
      toast.success(
        `${generated.generated_count} export record${generated.generated_count !== 1 ? 's' : ''} generated for ${generated.year}.`,
      )

      // Refresh the list
      const listRes = await fetch('/api/settings/payments/tax-documents')
      if (listRes.ok) {
        const listBody = (await listRes.json()) as { exports: Nec1099ExportRow[] }
        setExports(listBody.exports)
      }
    } catch {
      toast.error('Could not connect to the server. Please try again.')
    } finally {
      setGenerating(false)
    }
  }

  return (
    <Card className="shadow-soft border-[var(--color-border)]">
      <CardHeader className="pb-4">
        <p className="text-[11px] font-bold uppercase tracking-[0.08em] text-[var(--color-stone)]">
          TAX DOCUMENTS
        </p>
        <p className="text-sm text-[var(--color-stone)] leading-6 mt-1">
          Year-end 1099-NEC export. Artists earning $600 or more require a 1099-NEC. Generate after December 31.
        </p>
      </CardHeader>

      <CardContent className="space-y-6">
        <Button
          onClick={handleGenerate}
          disabled={generating}
          className="bg-[var(--color-onyx)] text-[var(--color-bone)] hover:bg-[var(--color-onyx)]/90"
        >
          {generating ? 'Generating...' : `Generate ${currentYear}`}
        </Button>

        {exports.length === 0 ? (
          <div className="py-12 text-center space-y-2">
            <p className="font-serif italic text-3xl font-normal text-[var(--color-onyx)]">
              No tax documents yet.
            </p>
            <p className="text-sm text-[var(--color-stone)]">
              No tax documents generated yet.
            </p>
          </div>
        ) : (
          <Table>
            <TableHeader>
              <TableRow className="border-[var(--color-border)]">
                <TableHead className="text-[11px] font-bold uppercase tracking-[0.08em] text-[var(--color-stone)]">
                  Year
                </TableHead>
                <TableHead className="text-[11px] font-bold uppercase tracking-[0.08em] text-[var(--color-stone)]">
                  Artist ID
                </TableHead>
                <TableHead className="text-[11px] font-bold uppercase tracking-[0.08em] text-[var(--color-stone)]">
                  Total Paid
                </TableHead>
                <TableHead className="text-[11px] font-bold uppercase tracking-[0.08em] text-[var(--color-stone)]">
                  Status
                </TableHead>
                <TableHead className="text-[11px] font-bold uppercase tracking-[0.08em] text-[var(--color-stone)]">
                  Generated
                </TableHead>
                <TableHead className="text-[11px] font-bold uppercase tracking-[0.08em] text-[var(--color-stone)]">
                  Actions
                </TableHead>
              </TableRow>
            </TableHeader>
            <TableBody>
              {exports.map((row) => (
                <TableRow key={row.id} className="border-[var(--color-border)]">
                  <TableCell
                    className="font-bold text-[var(--color-onyx)]"
                    style={{ fontVariantNumeric: 'tabular-nums' }}
                  >
                    {row.year}
                  </TableCell>
                  <TableCell className="font-mono text-xs text-[var(--color-stone)]">
                    {row.artist_id}
                  </TableCell>
                  <TableCell
                    className="text-[var(--color-onyx)]"
                    style={{ fontVariantNumeric: 'tabular-nums' }}
                  >
                    {formatDollars(row.total_paid_cents)}
                  </TableCell>
                  <TableCell>
                    {row.nec_threshold_met ? (
                      <span className="text-xs font-medium text-[var(--color-onyx)]">
                        Threshold met
                      </span>
                    ) : (
                      <span className="text-xs text-[var(--color-stone)]">Below threshold</span>
                    )}
                  </TableCell>
                  <TableCell className="text-sm text-[var(--color-stone)]">
                    {formatDate(row.generated_at)}
                  </TableCell>
                  <TableCell>
                    {row.csv_url !== null ? (
                      <a
                        href={row.csv_url}
                        download
                        className="text-sm font-medium text-[var(--color-onyx)] underline underline-offset-4 hover:text-[var(--color-stone)] transition-colors"
                      >
                        Download CSV
                      </a>
                    ) : (
                      <span className="text-sm text-[var(--color-stone)]">—</span>
                    )}
                  </TableCell>
                </TableRow>
              ))}
            </TableBody>
          </Table>
        )}
      </CardContent>
    </Card>
  )
}
